<script setup lang="ts">
import {ref,nextTick} from 'vue';
type Column={key:string;name:string;kind:string};
const props=defineProps<{columns:Column[];csrf:string;disabled:boolean}>();const emit=defineEmits<{saved:[Column[]];working:[boolean]}>();
const opened=ref(false),rows=ref<Column[]>([]),busy=ref(false),error=ref(''),confirmClose=ref(false),baseline=ref('');
const kinds:Record<string,string>={todo:'К выполнению',doing:'В работе',done:'Завершено'};
function open(){if(props.disabled)return;rows.value=props.columns.map(c=>({key:c.key,name:c.name,kind:c.kind}));baseline.value=JSON.stringify(rows.value);opened.value=true;error.value='';confirmClose.value=false;nextTick(()=>document.querySelector<HTMLButtonElement>('.board-settings button')?.focus())}
function close(){if(busy.value)return;if(JSON.stringify(rows.value)!==baseline.value)confirmClose.value=true;else opened.value=false}
function reorder(i:number,delta:number){const target=i+delta;if(target<0||target>=rows.value.length)return;[rows.value[i],rows.value[target]]=[rows.value[target],rows.value[i]]}
async function save(){if(busy.value)return;busy.value=true;emit('working',true);error.value='';try{const r=await fetch('/board-columns',{method:'PUT',credentials:'same-origin',headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':props.csrf},body:JSON.stringify({columns:rows.value.map(c=>({...c,key:c.key||null}))})});const d=await r.json();if(!r.ok)throw Error(d.errors?Object.values(d.errors).flat().join(' '):d.message||'Не удалось сохранить');emit('saved',d.columns);opened.value=false}catch(e){error.value=e instanceof Error?e.message:'Ошибка соединения'}finally{busy.value=false;emit('working',false)}}
function key(e:KeyboardEvent){if(e.key==='Escape'){e.stopPropagation();close()}if(e.key==='Tab'){const nodes=Array.from(document.querySelectorAll<HTMLElement>('.board-settings button:not(:disabled),.board-settings input:not(:disabled),.board-settings select:not(:disabled)')).filter(n=>!n.closest('fieldset:disabled'));const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}
</script>
<template><button :disabled="disabled" @click="open">Настроить столбцы</button><div v-if="opened" class="overlay board-settings-overlay" @click.self="close" @keydown="key"><section class="modal board-settings" role="dialog" aria-modal="true" aria-labelledby="board-settings-title"><div class="detail-head"><h2 id="board-settings-title">Столбцы доски</h2><button :disabled="busy" aria-label="Закрыть настройки столбцов" @click="close">×</button></div><p class="muted">Столбцы общие для твоего аккаунта. Названия и порядок можно менять. Тип определяет, считаются задачи новыми, в работе или завершёнными.</p><p v-if="error" class="error" role="alert">{{error}}</p><div v-if="confirmClose" class="extras-confirm"><p>Закрыть без сохранения?</p><button @click="opened=false">Закрыть без сохранения</button><button @click="confirmClose=false">Продолжить</button></div><form @submit.prevent="save"><fieldset :disabled="busy||confirmClose"><div v-for="(c,i) in rows" :key="c.key||'new-'+i" class="column-setting-row"><label>Название<input v-model="c.name" required maxlength="80"></label><label>Тип<select v-model="c.kind" :disabled="!!c.key"><option v-for="(name,key) in kinds" :key="key" :value="key">{{name}}</option></select></label><div class="actions"><button type="button" :disabled="i===0" @click="reorder(i,-1)" aria-label="Столбец левее">←</button><button type="button" :disabled="i===rows.length-1" @click="reorder(i,1)" aria-label="Столбец правее">→</button><button v-if="!['todo','doing','done'].includes(c.key)" type="button" @click="rows.splice(i,1)">Убрать</button></div></div><p class="muted">Удаляется только пустой дополнительный столбец, включая отсутствие задач в архиве и корзине. Три основных столбца остаются, но их можно переименовать.</p><div class="actions"><button type="button" :disabled="rows.length>=20" @click="rows.push({key:'',name:'Новый столбец',kind:'todo'})">＋ Столбец</button><button class="primary">Сохранить доску</button></div></fieldset></form></section></div></template>
